export const vocabById = new Map(vocabulary.map((v) => [v.id, v]))

export function vocabByDeck(deckId: string): VocabEntry[] {
  return vocabulary.filter((v) => v.deck === deckId)
}

/** Полная словарная форма: артикль + слово + множественное число */
export function fullForm(v: VocabEntry): string {
  const base = v.article ? `${v.article} ${v.de}${v.plural ? `, ${v.plural}` : ''}` : v.de
  return base
}

export const totalVocab = vocabulary.length
